import copy, hashlib, json, os, random, tempfile
from app import AuditChain, ZERO

random.seed(1234)
chain = AuditChain(os.path.join(tempfile.mkdtemp(), "x"))

def rec(t, seq, prev, ev):
    it = {"tenant": t, "seq": seq, "event": ev, "prev": prev, "hash": ""}
    it["hash"] = AuditChain._hash(it)
    return it

def build(entries):
    return ("".join(json.dumps(e, ensure_ascii=False, separators=(",", ":")) + "\n"
                    for e in entries)).encode()

def random_snapshot():
    tenants = ["a", {"k": "值α", "n": 1}, 7, "z"]
    tails = {t: ZERO for t in tenants}
    counts = {t: 0 for t in tenants}
    entries = []
    for _ in range(random.randint(0, 12)):
        t = random.choice(tenants)
        seq = counts[t] + 1
        e = rec(t, seq, tails[t], {"x": "é" * random.randint(0, 3)})
        tails[t], counts[t] = e["hash"], seq
        entries.append(e)
    return build(entries)

def cuts(data):
    bounds = sorted(random.sample(range(len(data) + 1), random.randint(0, min(6, len(data)))))
    out, start = [], 0
    for b in bounds:
        out.append(data[start:b]); start = b
    out.append(data[start:])
    if random.random() < 0.3:
        out.insert(random.randrange(len(out) + 1), b"")
    return out

mismatch_makers = [
    lambda m: (dict(m, byte_length=m["byte_length"] + 1),),
    lambda m: (dict(m, byte_sha256="1"*64),),
    lambda m: (dict(m, tenants=list(reversed(m["tenants"]))),),
]

for i in range(400):
    data = random_snapshot()
    m = chain.manifest_bytes(data)
    pieces = cuts(data)
    mode = random.random()
    if mode < 0.7:
        man = copy.deepcopy(m)
    elif mode < 0.8:
        man = copy.deepcopy(m); man["byte_length"] += 1
    elif mode < 0.9:
        man = copy.deepcopy(m); man["byte_sha256"] = "9"*64
    else:
        man = copy.deepcopy(m)
        if man["tenants"]:
            man["tenants"][0]["count"] += 1
        else:
            man["byte_length"] += 1
    r_s = chain.verify_manifest_stream(iter(pieces), copy.deepcopy(man))
    r_b = chain.verify_manifest_bytes(data, copy.deepcopy(man))
    r_c = chain.verify_manifest_chunks(iter(pieces), copy.deepcopy(man))
    assert r_s == r_b == r_c, (i, r_s, r_b, r_c, pieces)

# corruption fuzz: splice a bad byte/record into a random point
for i in range(300):
    data = random_snapshot()
    if not data:
        continue
    kind = random.randrange(4)
    pos = random.randrange(len(data))
    if kind == 0:
        bad = data[:pos] + b"\xff" + data[pos+1:]           # bad utf-8
    elif kind == 1:
        bad = data[:pos] + b"X" + data[pos:]               # junk char
    elif kind == 2:
        bad = data[:pos] + b"\r\n"[random.randrange(2):random.randrange(2)+0:1] if False else data
        bad = data.replace(b'"seq":1', b'"seq":2', 1)      # seq break if present
        if bad == data:
            bad = data[:pos] + b"\xc3" + data[pos:]        # truncated utf8 lead
    else:
        bad = data[:data.rfind(b"\n")] + b""               # drop last record
    m = chain.manifest_bytes(data)
    pieces = cuts(bad)
    r_s = chain.verify_manifest_stream(iter(pieces), copy.deepcopy(m))
    r_b = chain.verify_manifest_bytes(bad, copy.deepcopy(m))
    assert r_s == r_b, (i, kind, r_s, r_b, bad, pieces)
    if not r_s["ok"]:
        assert r_s["reason"] in ("missing", "sequence", "digest"), r_s
print("fuzz OK")
